insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('expense-receipts','expense-receipts',false,10485760,array['image/jpeg','image/png','application/pdf']) on conflict(id) do nothing;
create policy "Store staff upload receipts" on storage.objects for insert to authenticated with check (bucket_id='expense-receipts' and exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.is_active and p.role::text='staff' and p.store_id::text=(storage.foldername(name))[1]));
create policy "Store staff read receipts" on storage.objects for select to authenticated using (bucket_id='expense-receipts' and exists(select 1 from public.profiles p where p.user_id=(select auth.uid()) and p.is_active and p.role::text='staff' and p.store_id::text=(storage.foldername(name))[1]));
